#!/usr/bin/env python3
"""Cloud-only exact-source OBS browser experiment; never changes installed product."""
import os,sys,platform,pathlib,hashlib,json,difflib,subprocess
assert os.environ.get("GITHUB_ACTIONS") == "true" and platform.system() == "Darwin"
assert platform.machine() == "arm64"
root=pathlib.Path(sys.argv[1]).resolve()
out=pathlib.Path(os.environ["AI_LIVE_OBS_COPY_EVIDENCE"]).resolve()
out.mkdir(parents=True,exist_ok=True)
assert subprocess.check_output(["git","-C",str(root),"rev-parse","HEAD"],text=True).strip()=="ba2f32bdf791005443988a4955e963663e16b1ed"
browser=root/"plugins/obs-browser"
assert subprocess.check_output(["git","-C",str(browser),"rev-parse","HEAD"],text=True).strip()=="3f0a2cdf378939ebe3c6f9ab36d4ea100c25aac2"
